import json, itertools, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# generate all valid triples (a,b,c) with a+b=c and distinct elements
triples = []
for a in L:
    for b in L:
        if a>=b: continue
        c = a+b
        if c in L and c not in (a,b):
            triples.append((a,b,c))
# backtracking search for exact cover of 45 elements with 15 triples
solution = None
nodes_explored = 0
used = set()

def backtrack(start, chosen):
    global solution, nodes_explored
    nodes_explored += 1
    if solution is not None:
        return True
    if len(chosen) == 15:
        if used == L:
            solution = list(chosen)
            return True
        return False
    # prune if remaining elements cannot fill triples
    remaining = L - used
    if len(remaining) < 3*(15-len(chosen)):
        return False
    for i in range(start, len(triples)):
        a,b,c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose this triple
        used.update((a,b,c))
        chosen.append((a,b,c))
        if backtrack(i+1, chosen):
            return True
        # undo
        chosen.pop()
        used.difference_update((a,b,c))
    return False

backtrack(0, [])
if solution:
    witness = {
        "polarity": "positive",
        "data": {"triples": solution}
    }
else:
    witness = {
        "polarity": "negative",
        "basis": "search",
        "search_exhausted": True,
        "nodes_explored": nodes_explored,
