print("WITNESS: "+json.dumps(witness))

import json
from itertools import combinations

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Precompute all valid triples (a,b,c) with a+b=c
triples = []
for a, b, c in combinations(L, 3):
    if a + b == c:
        triples.append((a, b, c))
    elif a + c == b:
        triples.append((a, c, b))
    elif b + c == a:
        triples.append((b, c, a))

# Build adjacency: for each element, which triples include it
adj = {x: [] for x in L}
for t in triples:
    for x in t:
        adj[x].append(t)

nodes_explored = 0
solution = None

def backtrack(remaining, chosen):
    global nodes_explored, solution
    nodes_explored += 1
    if not remaining:
        solution = chosen[:]
        return True
    # choose the smallest element to reduce branching
    x = min(remaining)
    for t in adj[x]:
        if all(elem in remaining for elem in t):
            new_rem = remaining - set(t)
            chosen.append(t)
            if backtrack(new_rem, chosen):
                return True
            chosen.pop()
    return False

found = backtrack(set(L), [])
if found:
    witness = {
        "polarity": "positive",
        "data": {"triples": solution}
    }
else:
    witness = {
        "polarity": "negative",
        "basis": "search",
        "search_exhausted": True,
        "nodes_explored": nodes_explored,
        "method": "depth‑first backtracking"
    }
print("WITNESS: " + json.dumps(witness))
